"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminEstoque() {
    // Virgin inventory
    const [inventory, setInventory] = useState<any[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [newProduct, setNewProduct] = useState({ product: "", category: "Finalizadores", stock: "", min: "5", price: "" });

    const handleAddProduct = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newProduct.product || !newProduct.price) return;

        const item = {
            id: Date.now(),
            ...newProduct,
            stock: parseInt(newProduct.stock) || 0,
            min: parseInt(newProduct.min) || 5,
        };

        setInventory([...inventory, item]);
        setNewProduct({ product: "", category: "Finalizadores", stock: "", min: "5", price: "" });
        setIsModalOpen(false);
    };

    const adjustStock = (id: number, amount: number) => {
        setInventory(prev => prev.map(item =>
            item.id === id ? { ...item, stock: Math.max(0, item.stock + amount) } : item
        ));
    };

    const deleteProduct = (id: number) => {
        if (confirm("Remover este produto do estoque?")) {
            setInventory(prev => prev.filter(item => item.id !== id));
        }
    };

    const totalStockValue = inventory.reduce((acc, item) => acc + (parseFloat(item.price.replace(",", ".")) * item.stock), 0);
    const lowStockCount = inventory.filter(item => item.stock <= item.min).length;

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <header className="mb-10 lg:mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Gestão de <span className="text-[#D4AF37]">Estoque</span>
                    </h1>
                    <p className="text-gray-400 text-sm">Controle de produtos para uso e revenda</p>
                </div>
                <Button onClick={() => setIsModalOpen(true)} className="gap-2 h-12 rounded-2xl shadow-lg shadow-[#D4AF37]/10">
                    <Icon name="Plus" className="w-4 h-4" /> Novo Produto
                </Button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                <div className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl flex items-center gap-6">
                    <div className="bg-[#D4AF37]/5 w-14 h-14 rounded-2xl flex items-center justify-center text-[#D4AF37]">
                        <Icon name="Boxes" className="w-7 h-7" />
                    </div>
                    <div>
                        <p className="text-gray-500 text-[10px] uppercase font-black tracking-widest">Itens Totais</p>
                        <h3 className="text-2xl font-bold tracking-tight">{inventory.length}</h3>
                    </div>
                </div>
                <div className="bg-[#111111] border border-red-500/20 p-8 rounded-3xl flex items-center gap-6">
                    <div className="bg-red-500/5 w-14 h-14 rounded-2xl flex items-center justify-center text-red-500">
                        <Icon name="AlertTriangle" className="w-7 h-7" />
                    </div>
                    <div>
                        <p className="text-gray-500 text-[10px] uppercase font-black tracking-widest">Estoque Crítico</p>
                        <h3 className="text-2xl font-bold tracking-tight text-red-500">{lowStockCount} itens</h3>
                    </div>
                </div>
                <div className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-3xl flex items-center gap-6">
                    <div className="bg-emerald-500/5 w-14 h-14 rounded-2xl flex items-center justify-center text-emerald-500">
                        <Icon name="DollarSign" className="w-7 h-7" />
                    </div>
                    <div>
                        <p className="text-gray-500 text-[10px] uppercase font-black tracking-widest">Valor Estimado</p>
                        <h3 className="text-2xl font-bold tracking-tight text-emerald-500">R$ {totalStockValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</h3>
                    </div>
                </div>
            </div>

            <div className="bg-[#111111] border border-[#1f1f1f] rounded-[40px] overflow-hidden shadow-2xl">
                <table className="w-full text-left">
                    <thead>
                        <tr className="border-b border-[#1f1f1f] bg-[#161616]/50">
                            <th className="p-8 text-[10px] uppercase tracking-widest text-gray-500 font-black">Produto</th>
                            <th className="p-8 text-[10px] uppercase tracking-widest text-gray-500 font-black">Categoria</th>
                            <th className="p-8 text-[10px] uppercase tracking-widest text-gray-500 font-black">Qtd. Atual</th>
                            <th className="p-8 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-[#1f1f1f]">
                        {inventory.length > 0 ? inventory.map((item) => (
                            <tr key={item.id} className="hover:bg-white/[0.01] transition-all group">
                                <td className="p-8">
                                    <p className="font-bold text-base mb-1">{item.product}</p>
                                    <p className="text-[#D4AF37] font-black text-[10px] uppercase tracking-widest">R$ {item.price}</p>
                                </td>
                                <td className="p-8">
                                    <span className="text-[9px] uppercase font-black text-white/40 bg-[#1a1a1a] px-3 py-1.5 rounded-full border border-[#222]">
                                        {item.category}
                                    </span>
                                </td>
                                <td className="p-8">
                                    <div className="flex items-center gap-4">
                                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${item.stock <= item.min ? 'bg-red-500/10 text-red-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                                            {item.stock}
                                        </div>
                                        {item.stock <= item.min && <Icon name="AlertCircle" className="w-5 h-5 text-red-500 animate-pulse" />}
                                    </div>
                                </td>
                                <td className="p-8">
                                    <div className="flex justify-center gap-3">
                                        <button onClick={() => adjustStock(item.id, 1)} className="w-10 h-10 rounded-xl bg-emerald-500/5 text-emerald-500 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all border border-emerald-500/10"><Icon name="Plus" className="w-4 h-4" /></button>
                                        <button onClick={() => adjustStock(item.id, -1)} className="w-10 h-10 rounded-xl bg-gray-800 text-gray-400 flex items-center justify-center hover:bg-white hover:text-black transition-all border border-transparent"><Icon name="Minus" className="w-4 h-4" /></button>
                                        <button onClick={() => deleteProduct(item.id)} className="w-10 h-10 rounded-xl bg-red-500/5 text-red-500 flex items-center justify-center hover:bg-red-500 hover:text-white transition-all border border-red-500/10"><Icon name="Trash2" className="w-4 h-4" /></button>
                                    </div>
                                </td>
                            </tr>
                        )) : (
                            <tr>
                                <td colSpan={4} className="p-20 text-center text-gray-600 italic">Nenhum produto em estoque.</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={() => setIsModalOpen(false)} />
                    <div className="relative w-full max-w-xl bg-[#111111] border border-[#1f1f1f] rounded-[40px] p-10 shadow-2xl animate-fade-in-up">
                        <header className="flex justify-between items-center mb-10">
                            <h2 className="text-3xl font-bold tracking-tighter italic">Novo Produto</h2>
                            <button onClick={() => setIsModalOpen(false)}><Icon name="X" className="w-8 h-8 text-gray-500" /></button>
                        </header>
                        <form onSubmit={handleAddProduct} className="space-y-8">
                            <Input value={newProduct.product} onChange={e => setNewProduct({ ...newProduct, product: e.target.value })} className="bg-[#1a1a1a] border-transparent h-14 rounded-2xl" placeholder="Nome do Produto / Item" />
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Preço Unitário (R$)</label>
                                    <Input value={newProduct.price} onChange={e => setNewProduct({ ...newProduct, price: e.target.value })} className="bg-[#1a1a1a] border-transparent h-14 rounded-2xl" placeholder="0,00" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Qtd. Inicial</label>
                                    <Input value={newProduct.stock} onChange={e => setNewProduct({ ...newProduct, stock: e.target.value })} type="number" className="bg-[#1a1a1a] border-transparent h-14 rounded-2xl" placeholder="0" />
                                </div>
                            </div>
                            <Button type="submit" className="w-full h-16 bg-[#D4AF37] text-black font-black uppercase tracking-[0.2em] rounded-2xl">Cadastrar no Estoque</Button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}
